from reference import Task
import concurrent.futures
import zlib

class Solver:
    def __init__(self):
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=4)

    def compress_chunk_1(self, chunk):
        compressor = zlib.compressobj(8, zlib.DEFLATED, 31, 8, zlib.Z_DEFAULT_STRATEGY)
        return compressor.compress(chunk) + compressor.flush()

    def compress_chunk_2(self, chunk):
        compressor = zlib.compressobj(8, zlib.DEFLATED, 31, 8, zlib.Z_DEFAULT_STRATEGY)
        return compressor.compress(chunk) + compressor.flush()

    def solve(self, problem, **kwargs):
        plaintext = problem["plaintext"]
        split_idx = len(plaintext) // 2
        chunk1 = plaintext[:split_idx]
        chunk2 = plaintext[split_idx:]

        future1 = self.executor.submit(self.compress_chunk_1, chunk1)
        future2 = self.executor.submit(self.compress_chunk_2, chunk2)

        comp = future1.result() + future2.result()
        return {"compressed_data": comp}

