import numpy as np
import time

N = 1660
A = np.random.randn(N, N)
A = A.T @ A + N * np.eye(N)

import scipy.linalg.lapack as lapack

def wrapper(arr):
    class ArrayWrapper:
        def __init__(self, arr):
            self.arr = arr
        def __array__(self, dtype=None):
            return self.arr
        @property
        def shape(self):
            return self.arr.shape
    return ArrayWrapper(arr)

t0 = time.time()
for _ in range(30):
    L = np.linalg.cholesky(A)
print("np.linalg.cholesky:", time.time() - t0)

