import numpy as np

class Solver:
    def __init__(self, **kwargs):
        pass

    def solve(self, problem: dict[str, np.ndarray]) -> dict[str, dict[str, list[list[complex]]]]:
        A = problem["matrix"]
        n = A.shape[0]

        Y = np.copy(A)
        Z = np.eye(n, dtype=complex)
        for _ in range(50):
            try:
                Y_inv = np.linalg.inv(Y)
                Z_inv = np.linalg.inv(Z)
            except np.linalg.LinAlgError:
                return {"sqrtm": {"X": []}}

            Y_next = 0.5 * (Y + Z_inv)

            if np.max(np.abs(Y - Y_next)) < 1e-10:
                Y = Y_next
                break

            Y = Y_next
            Z = 0.5 * (Z + Y_inv)

        return {"sqrtm": {"X": Y.tolist()}}

