from typing import Any
import numpy as np
from scipy.stats import distributions
import concurrent.futures

class Solver:
    def __init__(self):
        self.executor = concurrent.futures.ThreadPoolExecutor(max_workers=4)

    def get_data(self, lst, n):
        return np.sort(np.fromiter(lst, dtype=np.float64, count=n))

    def get_diff(self, data1, data2, n):
        cdf = np.searchsorted(data2, data1, side='right')
        diff = np.arange(1, n + 1) - cdf
        return max(diff.max(), -diff.min() + 1)

    def solve(self, problem: dict[str, Any]) -> dict[str, Any]:
        sample1 = problem["sample1"]
        sample2 = problem["sample2"]
        n = len(sample1)

        f1 = self.executor.submit(self.get_data, sample1, n)
        f2 = self.executor.submit(self.get_data, sample2, n)

        data1 = f1.result()
        data2 = f2.result()

        f3 = self.executor.submit(self.get_diff, data1, data2, n)
        f4 = self.executor.submit(self.get_diff, data2, data1, n)

        max_diff = max(f3.result(), f4.result())
        d = float(max_diff) / n

        prob = distributions.kstwo.sf(d, np.round(n / 2.0))

        return {"statistic": float(d), "pvalue": float(prob)}
